"""A book of parcels with a cached total."""


class ParcelBook:
    def __init__(self):
        self._parcels = []
        self._total = None

    def add(self, parcel):
        """Add one parcel to the book."""
        self._parcels.append(parcel)

    def total(self):
        """Return the total grams of the parcels in the book."""
        if self._total is None:
            self._total = sum(x.grams for x in self._parcels)
        return self._total

    def count(self):
        """Return how many parcels the book holds."""
        return len(self._parcels)


def group_by_depot(parcels):
    """Return a dict from depot to the list of parcels with that depot."""
    groups = {}
    for x in parcels:
        groups.setdefault(x.depot, []).append(x)
    return groups

